"use client";

import { useState, useEffect, useCallback } from "react";
import { toast } from "react-toastify";
import { FaUpload, FaTrash } from "react-icons/fa";
import axiosInstance from "@/utils/axiosInstance";

interface ProductImageUploaderProps {
  productId: string;
}

const ProductImageUploader = ({ productId }: ProductImageUploaderProps) => {
  const [images, setImages] = useState<
    { position: number; productPictureUrl: string | null; pictureId: number | null }[]
  >([]);
  const [loading, setLoading] = useState<{ [key: number]: boolean }>({}); // Loading states for each position

  // Fetch images function
  const fetchImages = useCallback(async () => {
    try {
      const response = await axiosInstance.get(`/pictures/${productId}`);

      setImages(
        [1, 2, 3].map((position) =>
          response.data.data.find((img: any) => img.position === position) || {
            pictureId: null,
            productPictureUrl: null,
            position,
          }
        )
      );
    } catch (error) {
      console.error("Failed to load images", error);
    }
  }, [productId]);

  // Fetch images when component mounts
  useEffect(() => {
    fetchImages();
  }, [fetchImages]);

  // Handle file upload
  const handleUpload = async (position: number, file: File) => {
    setLoading((prev) => ({ ...prev, [position]: true })); // Disable button
    try {
      const formData = new FormData();
      formData.append("file", file);

      await axiosInstance.post(`/pictures/${productId}/${position}/upload`, formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      toast.success(`Picture ${position} uploaded successfully!`);
      await fetchImages();
    } catch (error) {
      toast.error("Failed to upload picture");
      console.error(error);
    } finally {
      setLoading((prev) => ({ ...prev, [position]: false })); // Re-enable button
    }
  };

  // Handle file selection
  const handleFileChange = (position: number, event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.files && event.target.files[0]) {
      handleUpload(position, event.target.files[0]);
    }
  };

  // Handle image deletion
  const handleDelete = async (position: number, pictureId: number | null) => {
    if (!pictureId) return;
    setLoading((prev) => ({ ...prev, [position]: true })); // Disable button
    try {
      await axiosInstance.delete(`/pictures/${productId}/${pictureId}/delete`);
      toast.success("Picture deleted successfully!");
      await fetchImages();
    } catch (error) {
      toast.error("Failed to delete picture");
      console.error(error);
    } finally {
      setLoading((prev) => ({ ...prev, [position]: false })); // Re-enable button
    }
  };

  return (
    <div className="grid grid-cols-3 gap-4">
      {[1, 2, 3].map((position) => {
        const image = images.find((img) => img.position === position);
        const isLoading = loading[position] || false; // Check loading state

        return (
          <div key={position} className="relative border rounded-lg p-2 flex flex-col items-center justify-center w-40 h-40 bg-gray-100">
            {image?.productPictureUrl ? (
              <img src={image.productPictureUrl} alt={`Product image ${position}`} className="w-full h-full object-cover rounded-lg" />
            ) : (
              <span className="text-gray-500 text-sm">No picture uploaded yet</span>
            )}

            {/* Buttons */}
            <div className="absolute top-2 right-2 flex space-x-2">
              <label className={`cursor-pointer ${isLoading ? "opacity-50 cursor-not-allowed" : ""} bg-blue-500 text-white p-1 rounded-full hover:bg-blue-700`}>
                <FaUpload size={16} />
                <input type="file" className="hidden" onChange={(e) => handleFileChange(position, e)} disabled={isLoading} />
              </label>
              {image?.pictureId && (
                <button
                  onClick={() => handleDelete(position, image.pictureId)}
                  className={`bg-red-500 text-white p-1 rounded-full hover:bg-red-700 ${isLoading ? "opacity-50 cursor-not-allowed" : ""}`}
                  disabled={isLoading}
                >
                  <FaTrash size={16} />
                </button>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default ProductImageUploader;