"use client";

import { useRouter, useParams } from "next/navigation";
import { useQuery } from "@tanstack/react-query";
import { useEffect, useState } from "react";
import { fetchProduct, fetchCategories } from "@/components/product/api";
import ProductForm from "@/components/product/ProductForm";
import ProductImageUploader from "@/components/product/ProductImageUploader";
import { Product, Category, ProductStatus } from "@/types/product";

const EditDraftProduct = () => {
  const router = useRouter();
  const { productId } = useParams() as { productId: string };

  const [initialValues, setInitialValues] = useState<Partial<Product>>({
    productName: "",
    detail: "",
    price: 0,
    weight: 0,
    productCategory: "",
  });

  const { data: product, isLoading: isProductLoading } = useQuery<Product>({
    queryKey: ["product", productId],
    queryFn: () => fetchProduct(productId),
    enabled: !!productId,
  });

  const { data: categories, isLoading: isCategoriesLoading } = useQuery<Category[]>({
    queryKey: ["categories"],
    queryFn: fetchCategories,
  });

  // State to show "Access Denied" before redirect
  const [isUnauthorized, setIsUnauthorized] = useState(false);

  useEffect(() => {
    if (product) {
      console.log("Fetched product:", product);

      // 🚨 Check if status is not "DRAFT"
      if (product.status !== ProductStatus.DRAFT) {
        console.warn("Unauthorized access: Redirecting to /403...");
        setIsUnauthorized(true); // Show "Access Denied" message
        setTimeout(() => router.push("/403"), 2000); // Redirect after 2 seconds
        return;
      }

      const matchedCategory = categories?.find((c) => c.categoryName === product.productCategory);

      setInitialValues({
        productName: product.productName || "",
        detail: product.detail || "",
        price: product.price || 0,
        weight: product.weight || 0,
        productCategory: matchedCategory ? String(matchedCategory.categoryId) : "",
      });
    }
  }, [product, categories, router]);

  if (isProductLoading || isCategoriesLoading) return <div>Loading...</div>;

  // 🚫 Show "Access Denied" before redirecting
  if (isUnauthorized) return <div className="text-red-600 text-center text-2xl">🚫 Access Denied! Redirecting...</div>;

  return (
    <div className="p-6 bg-white shadow-md rounded-lg">
      <h2 className="text-3xl font-semibold mb-4">Edit Product Draft</h2>
      {initialValues.productName ? (
        <>
          <ProductForm initialValues={initialValues} categories={categories || []} productId={productId} />

          <div className="mt-6">
            <h3 className="text-xl font-semibold mb-2">Product Images</h3>
            <ProductImageUploader productId={productId} />
          </div>

          <button
            type="button"
            onClick={() => console.log("Submitting...")}
            className="mt-4 px-4 py-2 bg-blue-600 text-white rounded-md"
          >
            Update Product
          </button>
        </>
      ) : (
        <div>Loading product details...</div>
      )}
    </div>
  );
};

export default EditDraftProduct;